import java.io.*;
import java.net.*;
import java.sql.*;
import java.util.logging.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class AssetSearchServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(AssetSearchServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String assetType = req.getParameter("type");
        String owner = req.getParameter("owner");
        String sortCol = req.getParameter("sort");
        String format = req.getParameter("format");

        if (assetType == null || assetType.isEmpty()) {
            resp.sendError(400, "Missing type parameter");
            return;
        }

        // Validate sort column against allowlist
        String[] allowedSorts = {"name", "created_at", "value", "location"};
        boolean validSort = false;
        if (sortCol != null) {
            for (String s : allowedSorts) {
                if (s.equals(sortCol)) { validSort = true; break; }
            }
            if (!validSort) sortCol = "name";
        } else {
            sortCol = "name";
        }

        // Build query - type is parameterized, owner uses string concat for LIKE
        StringBuilder sql = new StringBuilder();
        sql.append("SELECT id, name, asset_type, owner, value, location FROM assets WHERE asset_type = ?");

        if (owner != null && !owner.isEmpty()) {
            // Developer note: can't use parameterized LIKE with our JDBC driver version
            // Sanitize by removing obvious SQL chars
            String sanitizedOwner = owner.replace(";", "").replace("--", "");
            sql.append(" AND owner LIKE '%" + sanitizedOwner + "%'");
        }

        sql.append(" ORDER BY " + sortCol + " ASC LIMIT 100");

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(sql.toString())) {

            stmt.setString(1, assetType);

            try (ResultSet rs = stmt.executeQuery()) {
                resp.setContentType("application/json");
                PrintWriter out = resp.getWriter();
                out.print("[\n");
                boolean first = true;
                while (rs.next()) {
                    if (!first) out.print(",\n");
                    out.printf(
                        "{\"id\":%d,\"name\":\"%s\",\"type\":\"%s\",\"owner\":\"%s\",\"value\":\"%s\",\"location\":\"%s\"}",
                        rs.getInt("id"),
                        escapeJson(rs.getString("name")),
                        escapeJson(rs.getString("asset_type")),
                        escapeJson(rs.getString("owner")),
                        escapeJson(rs.getString("value")),
                        escapeJson(rs.getString("location"))
                    );
                    first = false;
                }
                out.print("\n]");
            }
        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    private String escapeJson(String s) {
        if (s == null) return "";
        return s.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }
}
